#!/usr/bin/env bash
set -euo pipefail

# Fase 6 -- Integración de OpenRouteService (routing real, geocodificación y
# optimización VROOM) + tiempo real (WebSocket) + cache (Redis opcional) +
# histórico de posiciones (PostGIS opcional). Cubre la lista de tecnologías
# que pediste, apoyándose en lo que ya existía sin tocar ninguna funcionalidad
# operativa:
#
#  1) ROUTING REAL (OpenRouteService): estimateRoute/estimateStopEtas (usadas al
#     crear/tocar una ruta) intentan primero una llamada real a ORS -- distancia,
#     duración y hora de llegada por parada siguiendo carretera de verdad, con el
#     perfil 'driving-hgv' (camión) por defecto. Si no hay ORS_API_KEY configurada,
#     o la llamada falla por lo que sea (sin red, cuota agotada...), cae automática
#     y silenciosamente a la aproximación por línea recta que ya existía -- cero
#     riesgo de romper la planificación por un proveedor externo opcional.
#  2) GEOCODIFICACIÓN (OpenRouteService): al crear/editar un almacén o un punto de
#     entrega, si falta lat/lng pero hay dirección, se intenta rellenar sola. Si no
#     hay clave o falla, se guarda igual que siempre (sin coordenadas).
#  3) OPTIMIZACIÓN AUTOMÁTICA (ORS Optimization / motor VROOM): nuevo botón
#     'Planificar automáticamente' en la pestaña Despacho del Planificador -- nuevo
#     endpoint POST /routes/auto-plan que agrupa y secuencia geográficamente los
#     pedidos validados sin ruta de un almacén/fecha/servicio, creando rutas draft
#     (la asignación de transportista/vehículo sigue el flujo ya existente). Acotado
#     a un máximo de pedidos/vehículos por llamada para respetar la capa gratuita de
#     ORS. Resuelve justo la pieza que optimization.routes.ts documentaba desde antes
#     como pendiente ('capa de secuenciación geográfica, a definir en integración').
#  4) TIEMPO REAL (WebSocket): nuevo servidor WebSocket (librería 'ws') en el mismo
#     puerto del backend (/ws), con salas por almacén y por envío. Cada acción de la
#     App Conductor (ping GPS, llegada/entrega de parada, cambio de estado) y cada
#     cambio de estado de ruta desde el Backoffice avisan en vivo a quien esté viendo
#     ese almacén/envío. El sondeo que ya existía (cada 20s en Despacho y Seguimiento)
#     NO se quita -- sigue siendo la red de seguridad si el WebSocket no está disponible.
#  5) ETA que se recalcula sola: cada ping GPS de la App Conductor comprueba si el
#     vehículo se ha desviado más de ~600m de la ruta prevista, o si ha pasado más de
#     10 minutos desde el último recálculo -- si alguna de las dos, se vuelve a pedir a
#     ORS la hora de llegada de las paradas pendientes desde la posición actual, y se
#     avisa en vivo. Limitado a como mucho un recálculo por minuto por envío.
#  6) CACHE (Redis opcional): toda llamada a OpenRouteService pasa antes por una cache
#     compartida -- usa Redis de verdad si configuras REDIS_URL, y si no, cae sola a
#     una cache en memoria del proceso (funciona igual de bien con una sola instancia,
#     solo que no sobrevive a un reinicio ni se comparte entre procesos).
#  7) HISTÓRICO DE POSICIONES (PostGIS opcional): nueva columna geoespacial en
#     tracking_event (fuera de las migraciones de Prisma, aplicada con su propio
#     script -- ver más abajo) + nuevo endpoint GET /shipments/:id/track que devuelve
#     el recorrido de un envío como línea simplificada. Si PostGIS no está disponible
#     en tu Neon (o el script de configuración falla), ese endpoint cae solo a devolver
#     los puntos en bruto sin simplificar -- nunca rompe nada.
#
# IMPORTANTE -- pasos manuales después de aplicar este script:
#  a) Añade en backend/.env la línea:  ORS_API_KEY=tu_clave_de_openrouteservice
#     (la clave NO va en este script -- es tuya, se queda solo en tu .env, que ya
#     está en .gitignore). Sin esa línea, todo sigue funcionando exactamente igual
#     que hasta ahora (aproximación por línea recta, sin geocodificación automática,
#     sin optimización automática) -- puedes aplicar este script ya mismo y añadir la
#     clave cuando quieras, sin prisa.
#  b) Opcional: si más adelante despliegas Redis, añade REDIS_URL=... en backend/.env
#     -- hasta entonces, la cache sigue funcionando en memoria, sin pasos extra.
#  c) Reinicia 'npm run dev' del backend (y del Backoffice) para que recojan los
#     ficheros nuevos y las dependencias nuevas.
#
# Sin cambios en schema.prisma -- el histórico geoespacial (PostGIS) se aplica con
# su propio script (npm run postgis:setup, ya incluido en el pie de este script) al
# margen de las migraciones de Prisma, así que no hace falta 'prisma db push'.
# Ejecutar desde la raíz del repo tms-production.

REPO_ROOT="$(pwd)"

