echo "OK: frontend/src/pages/PlannerPage.tsx"

echo
echo "=== Instalando dependencias nuevas del backend (ws, ioredis) ==="
(cd "$REPO_ROOT/backend" && npm install)
echo "=== Compilando backend ==="
(cd "$REPO_ROOT/backend" && npm run build)
echo "=== Configurando PostGIS (histórico de posiciones) ==="
echo "(si tu plan de Neon no permite crear extensiones, se avisará y el resto de la Fase 6 sigue funcionando igual)"
(cd "$REPO_ROOT/backend" && npm run postgis:setup) || true
echo "=== Compilando Backoffice ==="
(cd "$REPO_ROOT/frontend" && npm run build)

echo
echo "Listo: Fase 6 (OpenRouteService + tiempo real + cache + histórico PostGIS)"
echo "aplicada. Recuerda añadir ORS_API_KEY (y opcionalmente REDIS_URL) en backend/.env"
echo "y reiniciar \"npm run dev\" del backend y del Backoffice."
